     1→/**
     2→ * GEDCOM 5.5.1 and 7.0 Parser
     3→ * Handles parsing of GEDCOM format files into structured TypeScript objects
     4→ */
     5→
     6→import type {
     7→  GedcomFile,
     8→  GedcomLine,
     9→  GedcomRecord,
    10→  ParsedDate,
    11→  ParsedIndividual,
    12→  ParsedFamily,
    13→  ValidationError,
    14→} from "./types";
    15→import { detectEncoding, normalizeEncoding } from "./encoding";
    16→
    17→export class GedcomParser {
    18→  private lines: GedcomLine[] = [];
    19→  private records: GedcomRecord[] = [];
    20→  private errors: ValidationError[] = [];
    21→  private gedcomVersion: "5.5.1" | "7.0" = "5.5.1";
    22→
    23→  /**
    24→   * Parse GEDCOM 5.5.1 or 7.0 text into structured format
    25→   * Automatically detects and normalizes encoding
    26→   */
    27→  parse(content: string): GedcomFile {
    28→    this.lines = [];
    29→    this.records = [];
    30→    this.errors = [];
    31→
    32→    // Step 1: Detect and normalize encoding (ANSEL -> UTF-8)
    33→    const detectedEncoding = detectEncoding(content);
    34→    let processedContent = content;
    35→
    36→    if (detectedEncoding === "ANSEL") {
    37→      processedContent = normalizeEncoding(content);
    38→    }
    39→
    40→    // Split into lines and filter empty lines
    41→    const rawLines = processedContent.split(/\r?\n/).filter((line) => line.trim());
    42→
    43→    // Parse each line and handle continuations
    44→    this.parseLines(rawLines);
    45→
    46→    // Build hierarchical record structure
    47→    this.buildRecords();
    48→
    49→    // Extract specific records
    50→    const header = this.records.find((r) => r.type === "HEAD");
    51→    const trailer = this.records.find((r) => r.type === "TRLR");
    52→    const individuals = this.records.filter((r) => r.type === "INDI");
    53→    const families = this.records.filter((r) => r.type === "FAM");
    54→    const sources = this.records.filter((r) => r.type === "SOUR");
    55→    const objects = this.records.filter((r) => r.type === "OBJE");
    56→
    57→    if (!header) {
    58→      throw new Error("Missing required HEAD record");
    59→    }
    60→    if (!trailer) {
    61→      throw new Error("Missing required TRLR record");
    62→    }
    63→
    64→    // Extract charset and version from header
    65→    const charsetLine = header.tags.get("CHAR")?.[0];
    66→
    67→    // Find GEDC > VERS nested structure
    68→    // Look for VERS lines that come after GEDC at level 1
    69→    let version = "5.5.1";
    70→    const gedcLines = header.tags.get("GEDC") || [];
    71→    if (gedcLines.length > 0) {
    72→      const gedcIndex = header.lines.indexOf(gedcLines[0]);
    73→      for (let i = gedcIndex + 1; i < header.lines.length; i++) {
    74→        const line = header.lines[i];
    75→        // Stop if we reach level 1 (sibling of GEDC)
    76→        if (line.level === 1) {
    77→          break;
    78→        }
    79→        // Found VERS as child of GEDC
    80→        if (line.tag === "VERS" && line.level === 2) {
    81→          version = line.value;
    82→          break;
    83→        }
    84→      }
    85→    }
    86→
    87→    const charset = charsetLine?.value || "UTF-8";
    88→
    89→    // Detect GEDCOM version (5.5.1 vs 7.0)
    90→    const detectedVersion = this.detectGedcomVersion(version);
    91→    this.gedcomVersion = detectedVersion;
    92→
    93→    return {
    94→      header,
    95→      individuals,
    96→      families,
    97→      sources,
    98→      objects,
    99→      trailer,
   100→      version,
   101→      charset,
   102→      gedcomVersion: detectedVersion,
   103→    };
   104→  }
   105→
   106→  /**
   107→   * Detect GEDCOM version from version string
   108→   */
   109→  private detectGedcomVersion(versionStr: string): "5.5.1" | "7.0" {
   110→    if (!versionStr) {
   111→      return "5.5.1"; // Default to 5.5.1
   112→    }
   113→
   114→    const normalized = versionStr.trim().toLowerCase();
   115→    if (normalized.includes("7.0") || normalized.startsWith("7")) {
   116→      return "7.0";
   117→    }
   118→
   119→    return "5.5.1";
   120→  }
   121→
   122→  /**
   123→   * Parse lines and handle continuation lines (CONT/CONC)
   124→   */
   125→  private parseLines(rawLines: string[]): void {
   126→    let i = 0;
   127→    while (i < rawLines.length) {
   128→      const line = rawLines[i];
   129→      const parsedLine = this.parseLine(line);
   130→
   131→      if (!parsedLine) {
   132→        i++;
   133→        continue;
   134→      }
   135→
   136→      // Handle continuation lines
   137→      let continuedValue = parsedLine.value;
   138→      let nextIndex = i + 1;
   139→
   140→      while (nextIndex < rawLines.length) {
   141→        const nextLine = rawLines[nextIndex];
   142→        const nextParsed = this.parseLine(nextLine);
   143→
   144→        // Check if it's a continuation line (CONT or CONC)
   145→        if (!nextParsed) {
   146→          break;
   147→        }
   148→
   149→        // Check if next line is at higher level or lower level with continuation tags
   150→        const nextLevel = this.getLevel(nextLine);
   151→        const currentLevel = parsedLine.level;
   152→
   153→        if (
   154→          nextLevel > currentLevel &&
   155→          (nextParsed.tag === "CONT" || nextParsed.tag === "CONC")
   156→        ) {
   157→          // CONT adds line break, CONC concatenates
   158→          if (nextParsed.tag === "CONT") {
   159→            continuedValue += "\n" + nextParsed.value;
   160→          } else {
   161→            continuedValue += nextParsed.value;
   162→          }
   163→          nextIndex++;
   164→        } else {
   165→          break;
   166→        }
   167→      }
   168→
   169→      parsedLine.value = continuedValue;
   170→      this.lines.push(parsedLine);
   171→      i = nextIndex;
   172→    }
   173→  }
   174→
   175→  /**
   176→   * Parse a single GEDCOM line
   177→   * Format: <level> <tag> [<xref>] [<value>]
   178→   */
   179→  private parseLine(line: string): GedcomLine | null {
   180→    // Match GEDCOM line pattern
   181→    // Level is required, tag is required, xref/value are optional
   182→    const match = line.match(
   183→      /^(\d+)\s+(@[\w#]+@)?\s*(\w+)(?:\s+(@[\w#]+@|.*))?$/
   184→    );
   185→
   186→    if (!match) {
   187→      return null;
   188→    }
   189→
   190→    const [, levelStr, xref, tag, valueOrPointer] = match;
   191→    const level = parseInt(levelStr, 10);
   192→
   193→    // Determine if valueOrPointer is a pointer or value
   194→    let pointer: string | undefined;
   195→    let value: string;
   196→
   197→    if (valueOrPointer?.match(/^@[\w#]+@$/)) {
   198→      pointer = valueOrPointer;
   199→      value = "";
   200→    } else {
   201→      value = valueOrPointer || "";
   202→    }
   203→
   204→    return {
   205→      level,
   206→      tag,
   207→      xref,
   208→      value: value.trim(),
   209→      pointer,
   210→    };
   211→  }
   212→
   213→  /**
   214→   * Get level from a line string
   215→   */
   216→  private getLevel(line: string): number {
   217→    const match = line.match(/^(\d+)\s+/);
   218→    return match ? parseInt(match[1], 10) : 0;
   219→  }
   220→
   221→  /**
   222→   * Build hierarchical record structure from lines
   223→   */
   224→  private buildRecords(): void {
   225→    const recordStack: GedcomRecord[] = [];
   226→    let currentRecord: GedcomRecord | null = null;
   227→    let _currentParent: GedcomRecord | null = null;
   228→
   229→    for (const line of this.lines) {
   230→      // Top-level record
   231→      if (line.level === 0) {
   232→        // Save previous record
   233→        if (currentRecord) {
   234→          this.records.push(currentRecord);
   235→        }
   236→
   237→        const type = this.getRecordType(line.tag, line.xref);
   238→        currentRecord = {
   239→          type,
   240→          id: line.xref?.replace(/@/g, ""),
   241→          lines: [line],
   242→          tags: new Map(),
   243→        };
   244→        recordStack.length = 0;
   245→        recordStack.push(currentRecord);
   246→
   247→        // Add to tag map
   248→        const existing = currentRecord.tags.get(line.tag) || [];
   249→        existing.push(line);
   250→        currentRecord.tags.set(line.tag, existing);
   251→      } else if (currentRecord) {
   252→        // Add to current record
   253→        currentRecord.lines.push(line);
   254→
   255→        // Add to tag map
   256→        const existing = currentRecord.tags.get(line.tag) || [];
   257→        existing.push(line);
   258→        currentRecord.tags.set(line.tag, existing);
   259→      }
   260→    }
   261→
   262→    // Save last record
   263→    if (currentRecord) {
   264→      this.records.push(currentRecord);
   265→    }
   266→  }
   267→
   268→  /**
   269→   * Determine record type from tag
   270→   */
   271→  private getRecordType(
   272→    tag: string,
   273→    _xref?: string
   274→  ): "INDI" | "FAM" | "HEAD" | "TRLR" | "SOUR" | "OBJE" | "OTHER" {
   275→    if (tag === "HEAD") return "HEAD";
   276→    if (tag === "TRLR") return "TRLR";
   277→    if (tag === "INDI") return "INDI";
   278→    if (tag === "FAM") return "FAM";
   279→    if (tag === "SOUR") return "SOUR";
   280→    if (tag === "OBJE") return "OBJE";
   281→    return "OTHER";
   282→  }
   283→
   284→  /**
   285→   * Parse GEDCOM date format
   286→   * GEDCOM 5.5.1: "15 JAN 1985", "JAN 1985", "1985", "ABT 1985", "BEF 1985", "AFT 1985", "BET 1975 AND 1985"
   287→   * GEDCOM 7.0: ISO 8601 format "1985-01-15", "1985-01", "1985"
   288→   * Returns ISO date (YYYY-MM-DD) or partial ISO date (YYYY-MM or YYYY) or null if invalid
   289→   */
   290→  parseDate(gedcomDate: string, version: "5.5.1" | "7.0" = "5.5.1"): string | null {
   291→    if (!gedcomDate || !gedcomDate.trim()) {
   292→      return null;
   293→    }
   294→
   295→    const trimmed = gedcomDate.trim();
   296→
   297→    // Try GEDCOM 7.0 ISO 8601 format first if version is 7.0
   298→    if (version === "7.0") {
   299→      const iso8601Result = this.parseDateISO8601(trimmed);
   300→      if (iso8601Result) {
   301→        return iso8601Result;
   302→      }
   303→    }
   304→
   305→    // Fall back to GEDCOM 5.5.1 format
   306→    const parsed = this.parseDateComponents(trimmed);
   307→
   308→    if (!parsed.year) {
   309→      return null;
   310→    }
   311→
   312→    // Validate day is reasonable
   313→    if (parsed.day && (parsed.day < 1 || parsed.day > 31)) {
   314→      return null;
   315→    }
   316→
   317→    // Build ISO date with available components
   318→    let isoDate = String(parsed.year).padStart(4, "0");
   319→
   320→    if (parsed.month) {
   321→      isoDate += "-" + String(parsed.month).padStart(2, "0");
   322→
   323→      if (parsed.day) {
   324→        isoDate += "-" + String(parsed.day).padStart(2, "0");
   325→      }
   326→    }
   327→
   328→    return isoDate;
   329→  }
   330→
   331→  /**
   332→   * Parse ISO 8601 date format used in GEDCOM 7.0
   333→   * Formats: "1985-01-15", "1985-01", "1985"
   334→   */
   335→  private parseDateISO8601(dateStr: string): string | null {
   336→    // Match ISO 8601 format
   337→    const iso8601Match = dateStr.match(/^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/);
   338→
   339→    if (!iso8601Match) {
   340→      return null;
   341→    }
   342→
   343→    const year = iso8601Match[1];
   344→    const month = iso8601Match[2];
   345→    const day = iso8601Match[3];
   346→
   347→    // Build result
   348→    let result = year;
   349→    if (month) {
   350→      result += "-" + month;
   351→      if (day) {
   352→        result += "-" + day;
   353→      }
   354→    }
   355→
   356→    return result;
   357→  }
   358→
   359→  /**
   360→   * Parse date components from GEDCOM date string
   361→   */
   362→  private parseDateComponents(dateStr: string): ParsedDate {
   363→    const result: ParsedDate = {
   364→      isApproximate: false,
   365→      raw: dateStr,
   366→    };
   367→
   368→    // Check for date qualifiers
   369→    let workingStr = dateStr.trim();
   370→    const qualifierMatch = workingStr.match(/^(ABT|BEF|AFT|BET)\s+/);
   371→    if (qualifierMatch) {
   372→      result.qualifier = qualifierMatch[1] as any;
   373→      result.isApproximate = true;
   374→      workingStr = workingStr.substring(qualifierMatch[0].length).trim();
   375→    }
   376→
   377→    // Handle "BET ... AND ..." format (e.g., "BET 1975 AND 1985" or "BET 1 JAN 1975 AND 1 JAN 1985")
   378→    if (result.qualifier === "BET") {
   379→      // Try full date format first: "BET 15 JAN 1975 AND 15 JAN 1985"
   380→      const betFullMatch = workingStr.match(
   381→        /^(\d{1,2})\s+(\w+)\s+(\d{4})\s+AND\s+(\d{1,2})\s+(\w+)\s+(\d{4})$/
   382→      );
   383→      if (betFullMatch) {
   384→        result.day = parseInt(betFullMatch[1], 10);
   385→        result.month = this.monthToNumber(betFullMatch[2]);
   386→        result.year = parseInt(betFullMatch[3], 10);
   387→        return result;
   388→      }
   389→
   390→      // Try year-only format: "BET 1975 AND 1985"
   391→      const betYearMatch = workingStr.match(/^(\d{4})\s+AND\s+(\d{4})$/);
   392→      if (betYearMatch) {
   393→        result.year = parseInt(betYearMatch[1], 10);
   394→        return result;
   395→      }
   396→    }
   397→
   398→    // Try full date format: "15 JAN 1985"
   399→    const fullMatch = workingStr.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})$/);
   400→    if (fullMatch) {
   401→      result.day = parseInt(fullMatch[1], 10);
   402→      result.month = this.monthToNumber(fullMatch[2]);
   403→      result.year = parseInt(fullMatch[3], 10);
   404→      return result;
   405→    }
   406→
   407→    // Try month-year format: "JAN 1985"
   408→    const monthYearMatch = workingStr.match(/^(\w+)\s+(\d{4})$/);
   409→    if (monthYearMatch) {
   410→      result.month = this.monthToNumber(monthYearMatch[1]);
   411→      result.year = parseInt(monthYearMatch[2], 10);
   412→      return result;
   413→    }
   414→
   415→    // Try year only: "1985"
   416→    const yearMatch = workingStr.match(/^(\d{4})$/);
   417→    if (yearMatch) {
   418→      result.year = parseInt(yearMatch[1], 10);
   419→      return result;
   420→    }
   421→
   422→    return result;
   423→  }
   424→
   425→  /**
   426→   * Convert month name to number (1-12)
   427→   */
   428→  private monthToNumber(monthName: string): number | undefined {
   429→    const months: Record<string, number> = {
   430→      JAN: 1,
   431→      FEB: 2,
   432→      MAR: 3,
   433→      APR: 4,
   434→      MAY: 5,
   435→      JUN: 6,
   436→      JUL: 7,
   437→      AUG: 8,
   438→      SEP: 9,
   439→      SEPT: 9,
   440→      OCT: 10,
   441→      NOV: 11,
   442→      DEC: 12,
   443→    };
   444→    return months[monthName.toUpperCase()];
   445→  }
   446→
   447→  /**
   448→   * Parse name in GEDCOM format
   449→   * Format: "Given /Surname/" or "Given" or "/Surname/"
   450→   */
   451→  parseName(gedcomName: string): { firstName?: string; lastName?: string } {
   452→    if (!gedcomName || !gedcomName.trim()) {
   453→      return {};
   454→    }
   455→
   456→    const trimmed = gedcomName.trim();
   457→
   458→    // Find surname between forward slashes
   459→    const surnameMatch = trimmed.match(/\/([^\/]*)\//);
   460→    const lastName = surnameMatch ? surnameMatch[1].trim() : undefined;
   461→
   462→    // Extract given names (everything before and after surname)
   463→    let firstName: string | undefined;
   464→    if (surnameMatch) {
   465→      // Remove the /surname/ part and trim
   466→      const withoutSurname = trimmed.replace(/\/[^\/]*\//, "").trim();
   467→      firstName = withoutSurname || undefined;
   468→    } else {
   469→      // No surname markers, entire thing is given name
   470→      firstName = trimmed || undefined;
   471→    }
   472→
   473→    return {
   474→      firstName: firstName || undefined,
   475→      lastName: lastName || undefined,
   476→    };
   477→  }
   478→
   479→  /**
   480→   * Validate GEDCOM file structure
   481→   */
   482→  validate(file: GedcomFile): ValidationError[] {
   483→    const errors: ValidationError[] = [];
   484→
   485→    // Check for required records
   486→    if (!file.header) {
   487→      errors.push({
   488→        message: "Missing required HEAD record",
   489→        severity: "error",
   490→      });
   491→    }
   492→
   493→    if (!file.trailer) {
   494→      errors.push({
   495→        message: "Missing required TRLR record",
   496→        severity: "error",
   497→      });
   498→    }
   499→
   500→    // Check for unique xrefs
   501→    const xrefSet = new Set<string>();
   502→    const allRecords = [
   503→      file.header,
   504→      ...file.individuals,
   505→      ...file.families,
   506→      file.trailer,
   507→    ].filter((r): r is GedcomRecord => r !== null && r !== undefined);
   508→
   509→    for (const record of allRecords) {
   510→      if (record.id) {
   511→        if (xrefSet.has(record.id)) {
   512→          errors.push({
   513→            message: `Duplicate xref: ${record.id}`,
   514→            severity: "error",
   515→          });
   516→        }
   517→        xrefSet.add(record.id);
   518→      }
   519→    }
   520→
   521→    // Check for broken references in families
   522→    const personIds = new Set(file.individuals.map((i) => i.id));
   523→    const familyIds = new Set(file.families.map((f) => f.id));
   524→
   525→    for (const family of file.families) {
   526→      const husbandLine = family.tags.get("HUSB")?.[0];
   527→      const wifeLine = family.tags.get("WIFE")?.[0];
   528→      const childLines = family.tags.get("CHIL") || [];
   529→
   530→      if (
   531→        husbandLine?.pointer &&
   532→        !personIds.has(husbandLine.pointer.replace(/@/g, ""))
   533→      ) {
   534→        errors.push({
   535→          message: `Broken reference in family ${family.id}: HUSB ${husbandLine.pointer} not found`,
   536→          severity: "warning",
   537→        });
   538→      }
   539→
   540→      if (
   541→        wifeLine?.pointer &&
   542→        !personIds.has(wifeLine.pointer.replace(/@/g, ""))
   543→      ) {
   544→        errors.push({
   545→          message: `Broken reference in family ${family.id}: WIFE ${wifeLine.pointer} not found`,
   546→          severity: "warning",
   547→        });
   548→      }
   549→
   550→      for (const childLine of childLines) {
   551→        if (
   552→          childLine.pointer &&
   553→          !personIds.has(childLine.pointer.replace(/@/g, ""))
   554→        ) {
   555→          errors.push({
   556→            message: `Broken reference in family ${family.id}: CHIL ${childLine.pointer} not found`,
   557→            severity: "warning",
   558→          });
   559→        }
   560→      }
   561→    }
   562→
   563→    // Check for broken family references in individuals
   564→    for (const person of file.individuals) {
   565→      const famcLines = person.tags.get("FAMC") || [];
   566→      const famsLines = person.tags.get("FAMS") || [];
   567→
   568→      for (const line of famcLines) {
   569→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   570→          errors.push({
   571→            message: `Broken reference in person ${person.id}: FAMC ${line.pointer} not found`,
   572→            severity: "warning",
   573→          });
   574→        }
   575→      }
   576→
   577→      for (const line of famsLines) {
   578→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   579→          errors.push({
   580→            message: `Broken reference in person ${person.id}: FAMS ${line.pointer} not found`,
   581→            severity: "warning",
   582→          });
   583→        }
   584→      }
   585→    }
   586→
   587→    return errors;
   588→  }
   589→
   590→  /**
   591→   * Parse individual record into structured data
   592→   */
   593→  parseIndividual(record: GedcomRecord): ParsedIndividual {
   594→    const id = record.id || "unknown";
   595→
   596→    // Extract names
   597→    const names: Array<{
   598→      full: string;
   599→      firstName?: string;
   600→      lastName?: string;
   601→    }> = [];
   602→    const nameLines = record.tags.get("NAME") || [];
   603→    for (const line of nameLines) {
   604→      const { firstName, lastName } = this.parseName(line.value);
   605→      names.push({
   606→        full: line.value,
   607→        firstName,
   608→        lastName,
   609→      });
   610→    }
   611→
   612→    // Extract sex
   613→    const sexLine = record.tags.get("SEX")?.[0];
   614→    const sex =
   615→      sexLine?.value === "M" || sexLine?.value === "F" || sexLine?.value === "X"
   616→        ? sexLine.value
   617→        : undefined;
   618→
   619→    // Extract birth information
   620→    const birtLine = record.tags.get("BIRT")?.[0];
   621→    const birthDate = birtLine
   622→      ? this.parseDateFromRecord(record, "BIRT")
   623→      : undefined;
   624→    const birthPlace = this.getPlaceFromEvent(record, "BIRT");
   625→
   626→    // Extract death information
   627→    const deathLine = record.tags.get("DEAT")?.[0];
   628→    const deathDate = deathLine
   629→      ? this.parseDateFromRecord(record, "DEAT")
   630→      : undefined;
   631→    const deathPlace = this.getPlaceFromEvent(record, "DEAT");
   632→
   633→    // Extract occupation
   634→    const occuLine = record.tags.get("OCCU")?.[0];
   635→    const occupation = occuLine?.value;
   636→
   637→    // Extract notes (skip empty notes)
   638→    const notes: string[] = [];
   639→    const noteLines = record.tags.get("NOTE") || [];
   640→    for (const line of noteLines) {
   641→      const noteValue = line.value.trim();
   642→      if (noteValue) {
   643→        notes.push(noteValue);
   644→      }
   645→    }
   646→
   647→    // Extract family references
   648→    const familiesAsChild: string[] = [];
   649→    const famcLines = record.tags.get("FAMC") || [];
   650→    for (const line of famcLines) {
   651→      if (line.pointer) {
   652→        familiesAsChild.push(line.pointer.replace(/@/g, ""));
   653→      }
   654→    }
   655→
   656→    const familiesAsSpouse: string[] = [];
   657→    const famsLines = record.tags.get("FAMS") || [];
   658→    for (const line of famsLines) {
   659→      if (line.pointer) {
   660→        familiesAsSpouse.push(line.pointer.replace(/@/g, ""));
   661→      }
   662→    }
   663→
   664→    return {
   665→      id,
   666→      names: names.length > 0 ? names : [{ full: "" }],
   667→      sex,
   668→      birthDate,
   669→      birthPlace,
   670→      deathDate,
   671→      deathPlace,
   672→      occupation,
   673→      notes,
   674→      familiesAsChild,
   675→      familiesAsSpouse,
   676→    };
   677→  }
   678→
   679→  /**
   680→   * Parse family record into structured data
   681→   */
   682→  parseFamily(record: GedcomRecord): ParsedFamily {
   683→    const id = record.id || "unknown";
   684→
   685→    // Extract spouse information
   686→    const husbandLine = record.tags.get("HUSB")?.[0];
   687→    const wifeLine = record.tags.get("WIFE")?.[0];
   688→    const husband = husbandLine?.pointer?.replace(/@/g, "");
   689→    const wife = wifeLine?.pointer?.replace(/@/g, "");
   690→
   691→    // Extract children
   692→    const children: string[] = [];
   693→    const childLines = record.tags.get("CHIL") || [];
   694→    for (const line of childLines) {
   695→      if (line.pointer) {
   696→        children.push(line.pointer.replace(/@/g, ""));
   697→      }
   698→    }
   699→
   700→    // Extract marriage information
   701→    const marriageDate = this.parseDateFromRecord(record, "MARR");
   702→    const marriagePlace = this.getPlaceFromEvent(record, "MARR") || undefined;
   703→
   704→    // Extract divorce information
   705→    const divorceDate = this.parseDateFromRecord(record, "DIV");
   706→
   707→    // Extract notes (skip empty notes)
   708→    const notes: string[] = [];
   709→    const noteLines = record.tags.get("NOTE") || [];
   710→    for (const line of noteLines) {
   711→      const noteValue = line.value.trim();
   712→      if (noteValue) {
   713→        notes.push(noteValue);
   714→      }
   715→    }
   716→
   717→    return {
   718→      id,
   719→      husband,
   720→      wife,
   721→      children,
   722→      marriageDate,
   723→      marriagePlace,
   724→      divorceDate,
   725→      notes,
   726→    };
   727→  }
   728→
   729→  /**
   730→   * Parse date from an event tag (BIRT, DEAT, MARR, etc.)
   731→   */
   732→  private parseDateFromRecord(
   733→    record: GedcomRecord,
   734→    eventTag: string
   735→  ): string | undefined {
   736→    const eventLines = record.tags.get(eventTag) || [];
   737→    for (const eventLine of eventLines) {
   738→      // Look for DATE substructure
   739→      const eventIndex = record.lines.indexOf(eventLine);
   740→
   741→      // Find DATE lines that are children of this event
   742→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   743→        const line = record.lines[i];
   744→
   745→        // Stop if we reach a line at the same or lower level as the event
   746→        if (line.level <= eventLine.level) {
   747→          break;
   748→        }
   749→
   750→        // Found a DATE child of this event
   751→        if (line.tag === "DATE") {
   752→          const parsed = this.parseDate(line.value, this.gedcomVersion);
   753→          if (parsed) {
   754→            return parsed;
   755→          }
   756→        }
   757→      }
   758→    }
   759→    return undefined;
   760→  }
   761→
   762→  /**
   763→   * Get place from event tag
   764→   */
   765→  private getPlaceFromEvent(
   766→    record: GedcomRecord,
   767→    eventTag: string
   768→  ): string | undefined {
   769→    const eventLines = record.tags.get(eventTag) || [];
   770→    for (const eventLine of eventLines) {
   771→      // Look for PLAC substructure
   772→      const eventIndex = record.lines.indexOf(eventLine);
   773→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   774→        const line = record.lines[i];
   775→        if (line.level <= eventLine.level) {
   776→          break;
   777→        }
   778→        if (line.tag === "PLAC") {
   779→          return line.value;
   780→        }
   781→      }
   782→    }
   783→    return undefined;
   784→  }
