   187→
   188→  /**
   189→   * Generate FAM record
   190→   */
   191→  private generateFamily(family: GedcomFamilyData): string {
   192→    const lines: string[] = [];
   193→
   194→    // Opening record
   195→    lines.push(`0 ${family.xref} FAM`);
   196→
   197→    // Husband (optional)
