   239→
   240→  /**
   241→   * Format individual GEDCOM line
   242→   * Format: "<level> [<xref>] <tag> [<value>]"
   243→   */
   244→  private formatLine(
   245→    level: number,
   246→    tag: string,
   247→    value?: string,
   248→    xref?: string
   249→  ): string {
   250→    let line = `${level}`;
   251→
   252→    if (xref) {
   253→      line += ` ${xref}`;
   254→    }
   255→
   256→    line += ` ${tag}`;
