   264→
   265→  /**
   266→   * Format date for GEDCOM output based on version
   267→   * GEDCOM 5.5.1: "15 JAN 1985"
   268→   * GEDCOM 7.0: "1985-01-15" (ISO 8601)
   269→   */
   270→  private formatDate(isoDate: string): string {
   271→    if (!isoDate) {
   272→      return "";
   273→    }
   274→
   275→    if (this.version === "7.0") {
   276→      // ISO 8601 format - already in correct format
   277→      return isoDate;
   278→    }
   279→
   280→    // GEDCOM 5.5.1 format - convert from ISO to traditional format
   281→    const parts = isoDate.split("-");
   282→    if (parts.length === 3) {
   283→      const day = String(parseInt(parts[2], 10));
   284→      const year = parts[0];
   285→      const monthIndex = parseInt(parts[1], 10) - 1;
   286→      const months = [
   287→        "JAN",
   288→        "FEB",
   289→        "MAR",
   290→        "APR",
   291→        "MAY",
   292→        "JUN",
   293→        "JUL",
   294→        "AUG",
   295→        "SEP",
   296→        "OCT",
   297→        "NOV",
   298→        "DEC",
   299→      ];
   300→      const month = months[monthIndex];
   301→      return `${day} ${month} ${year}`;
   302→    } else if (parts.length === 2) {
   303→      // Month-year only
   304→      const year = parts[0];
   305→      const monthIndex = parseInt(parts[1], 10) - 1;
   306→      const months = [
   307→        "JAN",
   308→        "FEB",
   309→        "MAR",
   310→        "APR",
   311→        "MAY",
   312→        "JUN",
   313→        "JUL",
   314→        "AUG",
   315→        "SEP",
   316→        "OCT",
   317→        "NOV",
   318→        "DEC",
   319→      ];
   320→      const month = months[monthIndex];
   321→      return `${month} ${year}`;
   322→    } else if (parts.length === 1) {
   323→      // Year only
   324→      return parts[0];
   325→    }
   326→
   327→    return isoDate;
   328→  }
   329→
   330→  /**
   331→   * Handle long lines with continuation
   332→   * Splits lines longer than maxLineLength using CONC/CONT
   333→   * CONC = concatenate (no space between continuation)
   334→   * CONT = continue (line break in original)
   335→   */
   336→  private formatLongLine(level: number, tag: string, value: string): string[] {
   337→    const lines: string[] = [];
   338→
   339→    if (!value || value.length === 0) {
   340→      return [this.formatLine(level, tag)];
   341→    }
   342→
   343→    // First line with tag
   344→    const firstLineMaxLength = this.maxLineLength - `${level} ${tag} `.length;
   345→
   346→    if (value.length <= firstLineMaxLength) {
   347→      // Fits in one line
   348→      return [this.formatLine(level, tag, value)];
   349→    }
   350→
   351→    // Split into multiple lines
   352→    let remaining = value;
   353→    let isFirst = true;
   354→
   355→    while (remaining.length > 0) {
   356→      if (isFirst) {
   357→        // First line with original tag
   358→        const chunk = remaining.substring(0, firstLineMaxLength);
   359→        lines.push(this.formatLine(level, tag, chunk));
   360→        remaining = remaining.substring(firstLineMaxLength);
   361→        isFirst = false;
   362→      } else {
   363→        // Continuation lines - prefer CONT for word boundaries
   364→        const contLineMaxLength =
   365→          this.maxLineLength - `${level + 1} CONT `.length;
   366→
   367→        if (remaining.length <= contLineMaxLength) {
   368→          // Last chunk
   369→          lines.push(this.formatLine(level + 1, "CONT", remaining));
   370→          remaining = "";
   371→        } else {
   372→          // Find word boundary for better readability
   373→          const chunk = remaining.substring(0, contLineMaxLength);
   374→          const lastSpace = chunk.lastIndexOf(" ");
   375→
   376→          if (lastSpace > 0 && lastSpace > contLineMaxLength / 2) {
   377→            // Use word boundary
   378→            lines.push(
   379→              this.formatLine(level + 1, "CONT", chunk.substring(0, lastSpace))
   380→            );
   381→            remaining = remaining.substring(lastSpace + 1);
   382→          } else {
   383→            // No good word boundary, use CONC for hard break
   384→            lines.push(this.formatLine(level + 1, "CONC", chunk));
   385→            remaining = remaining.substring(contLineMaxLength);
   386→          }
   387→        }
   388→      }
   389→    }
   390→
   391→    return lines;
   392→  }
   393→
   394→  /**
