          relationships.push({
            id: generateId(),
            personId: childVamsaId,
            relatedPersonId: wifeId,
            type: "CHILD",
            isActive: true,
          });
        }
      }
    }
  }

  return {
    people,
    relationships,
    errors,
    warnings,
  };
}

