        isLiving: true,
      },
      {
        id: "p5",
        firstName: "Eve",
        lastName: "Child2",
        gender: "FEMALE",
        isLiving: true,
      },
    ];

    const relationships: VamsaRelationship[] = [
      // First marriage
      {
        personId: "p1",
        relatedPersonId: "p2",
