        isActive: true,
      },
      {
        personId: "p2",
        relatedPersonId: "p1",
        type: "SPOUSE",
        isActive: true,
      },
      {
        personId: "p1",
        relatedPersonId: "p3",
        type: "PARENT",
        isActive: true,
      },
      {
        personId: "p2",
        relatedPersonId: "p3",
