        isActive: true,
      },
      // Second marriage
      {
        personId: "p1",
        relatedPersonId: "p4",
        type: "SPOUSE",
        isActive: true,
      },
      {
        personId: "p4",
        relatedPersonId: "p1",
        type: "SPOUSE",
        isActive: true,
      },
      {
        personId: "p1",
        relatedPersonId: "p5",
        type: "PARENT",
        isActive: true,
      },
      {
        personId: "p4",
        relatedPersonId: "p5",
        type: "PARENT",
        isActive: true,
      },
    ];

    const result = roundtripExportImport(people, relationships);

    // Should have 2 families (one per marriage)
    expect(result.mapped.families).toHaveLength(2);
    expect(result.reMapped.families).toHaveLength(2);
  });

  it("should preserve all data types through export-import-export cycle", () => {
    const people: VamsaPerson[] = [
      {
        id: "p1",
        firstName: "John",
        lastName: "Smith",
        dateOfBirth: new Date("1985-01-15"),
        dateOfPassing: new Date("2020-06-10"),
        birthPlace: "New York, NY",
        gender: "MALE",
        profession: "Engineer",
        bio: "Professional background",
        isLiving: false,
      },
      {
