  });

  it("should generate valid GEDCOM from empty database", () => {
    const people: VamsaPerson[] = [];
    const relationships: VamsaRelationship[] = [];

    // 1. Map to GEDCOM
    const mapped = mapper.mapToGedcom(people, relationships);

    // 2. Generate GEDCOM
